//! Actual owner/implementation/content index admission and XML kind retention.
use super::*;
#[test]
fn template_document_owner_xml_kind_joint_backing_copy_refusal_reuse_and_recovery(){
 let mut doc=crate::html::parse("<html><body></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);let mut b=Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state};let Value::Host(xml)=b.create_xml_document(MAIN_IMPLEMENTATION,&[Value::Null,Value::String(String::new())]).unwrap()else{panic!("xml")};let Value::Host(host)=b.create_expanded_element(xml,&[Value::String(HTML_NAMESPACE.into()),Value::String("template".into())]).unwrap()else{panic!("host")};let before=(b.state.retained,b.state.inert_documents.backing_bytes(),b.state.inert_documents.entries.len(),b.state.inert_documents.template_documents.len(),b.state.inert_documents.template_contents.len(),b.doc.nodes.len());let limit=b.state.retained_limit;let copies=b.state.copy_work;
 for storage in [true,false]{if storage{b.state.retained_limit=before.0;}else{b.state.copy_work=0;}assert!(b.template_content(host).is_err());assert_eq!((b.state.retained,b.state.inert_documents.backing_bytes(),b.state.inert_documents.entries.len(),b.state.inert_documents.template_documents.len(),b.state.inert_documents.template_contents.len(),b.doc.nodes.len()),before);b.state.retained_limit=limit;b.state.copy_work=copies;}
 let Value::Host(fragment)=b.template_content(host).unwrap()else{panic!("content")};let owner=b.state.inert_documents.node(fragment).unwrap().owner;let Kind::TemplateDocument{kind,implementation,..}=b.state.inert_documents.node(owner).unwrap().kind else{panic!("associated document")};assert_eq!(kind,crate::html::DocumentKind::Xml);assert_eq!(b.state.inert_documents.template_documents.get(&xml),Some(&owner));assert_eq!(b.state.inert_documents.template_contents.get(&host),Some(&fragment));assert_eq!(b.state.retained,before.0+b.state.inert_documents.backing_bytes()-before.1);assert!(b.inert_implementation(implementation));let retained=b.state.retained;assert!(matches!(b.template_content(host).unwrap(),Value::Host(value) if value==fragment));assert_eq!(b.state.retained,retained);let Value::Host(nested)=b.create_expanded_element(owner,&[Value::String(HTML_NAMESPACE.into()),Value::String("template".into())]).unwrap()else{panic!("nested")};let Value::Host(nested_content)=b.template_content(nested).unwrap()else{panic!("nested content")};assert_eq!(b.state.inert_documents.node(nested_content).unwrap().owner,owner);assert_eq!(b.inert_document_kind_for_node(nested_content),Some(crate::html::DocumentKind::Xml));
}
